/**
 * Page Object for PIM — Employee Management
 * Source: cypress/e2e/orangehrm-pim.cy.js
 * Generated by: /tw-e2e-page-object
 *
 * Selector strategy (third-party app — data-testid cannot be added):
 *   1. input[name]                                       — stable HTML name attributes
 *   2. cy.contains('.oxd-label', ...).closest().find()   — label-anchored (stable)
 *   3. cy.contains('button', 'text')                     — text-based (moderate)
 *   REMOVED: all .oxd-input property declarations (caused selector collision —
 *   5 different fields all resolved to the same .oxd-input class)
 *   REMOVED: addButton = 'button' (bare tag selector)
 *   TODO: If OrangeHRM exposes data-testid, replace label-anchored selectors.
 */
class PIMPage {

    // --- Stable selectors ---
    // Form fields with input[name] attributes (confirmed from OrangeHRM HTML)
    firstNameInput  = 'input[name="firstName"]';
    middleNameInput = 'input[name="middleName"]';
    lastNameInput   = 'input[name="lastName"]';

    submitButton = 'button[type="submit"]';
    resetButton  = 'button[type="reset"]';

    // --- Assertions ---

    verifyEmployeeInformationSectionVisible() {
        cy.contains('h5', 'Employee Information').should('be.visible');
        return this;
    }

    verifySearchFormVisible() {
        cy.get('.oxd-form').should('be.visible');
        return this;
    }

    verifyTableVisible() {
        cy.get('.oxd-table').should('be.visible');
        return this;
    }

    verifyTableHeaders() {
        // Increased timeout: table headers render after API response in CI
        cy.get('.oxd-table-header', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-table-header-cell', 'Id', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-table-header-cell', 'First Name', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-table-header-cell', 'Last Name', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-table-header-cell', 'Job Title', { timeout: 15000 }).should('be.visible');
        return this;
    }

    // --- Actions ---

    searchForEmployee(employeeId) {
        // Label-anchored: survives DOM position changes
        cy.contains('.oxd-label', 'Employee Id')
            .closest('.oxd-input-group')
            .find('input')
            .type(employeeId);
        return this;
    }

    clickSearch() {
        cy.get(this.submitButton).click();
        return this;
    }

    clickReset() {
        cy.get(this.resetButton).click();
        return this;
    }

    clickAdd() {
        // Text-based: survives button style class changes
        cy.contains('button', 'Add').click();
        return this;
    }

    verifySearchResults() {
        cy.get('.oxd-table-body').should('be.visible');
        return this;
    }

    // --- Add Employee page ---

    verifyAddEmployeePage() {
        // Increased timeout: form renders asynchronously in CI
        cy.contains('h6', 'Add Employee', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-label', 'First Name', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-label', 'Middle Name', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-label', 'Last Name', { timeout: 15000 }).should('be.visible');
        cy.contains('.oxd-label', 'Employee Id', { timeout: 15000 }).should('be.visible');
        return this;
    }

    fillEmployeeDetails(firstName, middleName, lastName) {
        cy.get(this.firstNameInput).type(firstName);
        cy.get(this.middleNameInput).type(middleName);
        cy.get(this.lastNameInput).type(lastName);
        return this;
    }

    toggleCreateLoginDetails() {
        // Target the switch by its label to avoid positional .oxd-switch-input
        // The toggle renders after the form — wait for it before interacting
        cy.contains('.oxd-label', 'Create Login Details', { timeout: 15000 })
            .closest('.oxd-input-group')
            .find('input[type="checkbox"]')
            .click({ force: true });
        return this;
    }

    fillLoginDetails(username, password, confirmPassword) {
        // Label-anchored selectors — already the correct pattern; kept and standardized
        cy.contains('.oxd-label', 'Username')
            .closest('.oxd-input-group')
            .find('input')
            .clear()
            .type(username);
        cy.contains('.oxd-label', /^Password$/)
            .closest('.oxd-input-group')
            .find('input')
            .type(password);
        cy.contains('.oxd-label', /^Confirm Password$/)
            .closest('.oxd-input-group')
            .find('input')
            .type(confirmPassword);
        return this;
    }

    verifyEmployeeDetailsEntered(firstName, middleName, lastName) {
        cy.get(this.firstNameInput).should('have.value', firstName);
        cy.get(this.middleNameInput).should('have.value', middleName);
        cy.get(this.lastNameInput).should('have.value', lastName);
        return this;
    }

    // --- Reset form assertion ---

    verifyEmployeeIdFieldIsEmpty() {
        // Label-anchored — replaces the former .oxd-input.eq(1) index selector
        cy.contains('.oxd-label', 'Employee Id')
            .closest('.oxd-input-group')
            .find('input')
            .should('have.value', '');
        return this;
    }
}

export default new PIMPage();
